def median(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Median
    Median is the middle value of a sorted dataset. If the dataset is an
    odd length, the median is the value separating the higher and lower
    halves. If the dataset is even length, median is the average of the
    two numbers in the middle:
    >>> median([1,2,3,4,5,6,7])
    4.0
    >>> median([2,4,6,8,10])
    6.0
    >>> median([1,3,3,5,7,9])
    5.0
    """
    sorted_numbers = sorted(numbers)
    mid = len(sorted_numbers) // 2

    if len(sorted_numbers) % 2 == 1:
        return sorted_numbers[mid]
    else:
        return (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2


