def max_depth_of_nested_paren(paren_string: str) -> int:
    """ Returns the maximum depth of nested parentheses in a given string """
    # We can only increment the depth if there is another set of parenthesis
    # that means we are not at the end of the string
    depth = 0

    for i, char in enumerate(paren_string):
