def has_close_elements_recursive(numbers: List[float], threshold: float, index: int) -> bool:
    """ Check if in given list of numbers, are any two numbers closer to each other than
    given threshold. This recursive version of has_close_elements was suggested by
    Prof. Eelco Visser to a discussion on the PyBites Slack.
    >>> has_close_elements_recursive([1.0, 2.0, 3.0], 0.5, 2)
    False
    >>> has_close_elements_recursive([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3, 5)
    True
    """
    if index > len(numbers) - 1:
        return False

    next_num = numbers[index]
    if next_num - numbers[index - 1] > threshold:
        return has_close_elements_recursive(numbers, threshold, index + 1)

    return has_close_elements_recursive(numbers, threshold, index + 1)

