    """ Input to this function is a string represented a single group of nested parentheses.
    Return the deepest level of nesting of parentheses.

    >>> parse_parens('()')
    1
    >>> parse_parens('(()())')
    2
    """
    level = 0
    max_level = 0
    for char in paren_string:
        if char == '(':
            level += 1
        else:
            level -= 1
        if level > max_level:
            max_level = level
    return max_level

    nested_parens = []

    for group in paren_string.split():
        nested = get_nested_parens(group)
        if nested:
            nested_parens.append(max(nested))
    return nested_parens

def get_nested_parens(paren_string: str):
    """ Given a paren string returns the deepest nesting depth

    >>> get_nested_parens('(()())')
    2
    """
    index = 0
    nested_parens = 0
    for char in paren_string:
        if char == '(':
            nested_parens += 1
        elif char == ')':
            nested_parens -= 1
        if nested_parens == 0:
            index += 1

    return index

