def parse_non_nested_parens(paren_string: str) -> int:
    """ Input to this function is a string consisting only of '(' and ')' characters.
    Output is the maximum nesting of parentheses.

    >>> parse_non_nested_parens('(()())')
    2
    >>> parse_non_nested_parens('(()()) ((())) () ((())()())')
    3
    """
    if len(paren_string) == 0:
        return 0
    for i in range(1, len(paren_string)):
        # If you add a group, you might see a group with less nesting, or you might see a group with more nesting.
        if paren_string[i] == '(':
            return max(parse_non_nested_parens(paren_string[:i]), parse_non_nested_parens(paren_string[i:]))
        else:
            return parse_non_nested_parens(paren_string[:i-1])
    return parse_non_nested_parens(paren_string[:1])


